React me state manage karne ke liye `useState` hook ka use karte hain. Jaise hi state change hoti hai, React UI ko re-render kar deta hai:

```tsx
import { useState } from 'react';

export function Counter() {
  const [count, setCount] = useState(0);
  return (
    <button onClick={() => setCount(count + 1)}>
      Clicked {count} times
    </button>
  );
}
```
